	{
		return true;
	}

	@Alpha
	@ConfigItem(
		keyName = "colour",
		name = "Colour",
		description = "Colour of the outline in the inventory",
		position = 4
	)
	default Color colour()
	{
		return new Color(0, 255, 255);
	}
}

